const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }), new winston.transports.Console() ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Try Lock Folder" } });
const redis = require('redis');
const crypto = require('crypto');
const folder = $input.first().json; // { id, path, suggested_type }

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

const LOCK_TTL_MS = 180000; // 3 min - renewed once per file by the Path-Worker (PROJ-72)
const ownerToken = crypto.randomUUID();
const lockKey = `alice:dms:scanner:lock:folder:${folder.id}`;
const lockValue = JSON.stringify({ owner: ownerToken, path: folder.path, folder_id: folder.id, started_at: new Date().toISOString() });

let acquired = false;
try {
  await client.connect();
  const res = await client.set(lockKey, lockValue, { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
  await client.incr(acquired ? 'alice:dms:scanner:dispatch:stats:dispatched' : 'alice:dms:scanner:dispatch:stats:skipped_locked').catch(() => {});
} catch(e) {
  logger.info(`[Dispatcher] Lock attempt error for folder ${folder.id}: ${e.message}`);
  acquired = false;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { ...folder, _lock_acquired: acquired, lock_owner: acquired ? ownerToken : null } }];

const redis = require('redis');
const folders = $('PG: Active Folders').all();
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

let dispatched = 0, skippedLocked = 0, startMs = 0;
try {
  await client.connect();
  const [d, s, startStr] = await Promise.all([
    client.get('alice:dms:scanner:dispatch:stats:dispatched'),
    client.get('alice:dms:scanner:dispatch:stats:skipped_locked'),
    client.get('alice:dms:scanner:dispatch:run_start')
  ]);
  dispatched = parseInt(d || '0', 10);
  skippedLocked = parseInt(s || '0', 10);
  startMs = parseInt(startStr || '0', 10);
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
}

return [{ json: {
  event: 'alice-dms-scanner-dispatch-complete',
  active_folders: folders.length,
  paths_dispatched: dispatched,
  paths_skipped_locked: skippedLocked,
  runtime_seconds: startMs > 0 ? Math.round((Date.now() - startMs) / 1000) : 0,
  completed_at: new Date().toISOString()
} }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }), new winston.transports.Console() ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Init Dispatcher Run" } });
const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
  await client.del(['alice:dms:scanner:dispatch:stats:dispatched', 'alice:dms:scanner:dispatch:stats:skipped_locked']);
  await client.set('alice:dms:scanner:dispatch:run_start', String(Date.now()));
