} catch(e) {
  try { await client.quit(); } catch(qe) {}
  logger.info('Redis unavailable for dispatch stats init, continuing: ' + e.message);
}
return $input.all();

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }), new winston.transports.Console() ], defaultMeta: { workflow: "alice-dms-scanner", node: "Code: Find Stale Paths" } });
const redis = require('redis');
const fs = require('fs');
const statsItem = $input.first().json;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

const outputItems = [];
let deletedFiles = 0;

try {
  await client.connect();
  const pathToHash = await client.hGetAll('alice:dms:path_to_hash');

  for (const [filePath, fileHash] of Object.entries(pathToHash || {})) {
    if (!fs.existsSync(filePath)) {
      await client.hDel('alice:dms:path_to_hash', filePath);
      await client.sRem('alice:dms:hash_to_paths:' + fileHash, filePath);
      const remaining = await client.sMembers('alice:dms:hash_to_paths:' + fileHash);
      const stillAlive = remaining.filter(p => { try { fs.accessSync(p, fs.constants.F_OK); return true; } catch(e) { return false; } });
      if (stillAlive.length === 0) {
        await client.sRem('alice:dms:processed', fileHash);
        deletedFiles++;
        outputItems.push({ json: { _stale_for_deletion: true, file_hash: fileHash, file_path: filePath, detected_at: new Date().toISOString() } });
        logger.info('[alice-dms-scanner] delete_file: ' + filePath + ' (hash: ' + fileHash + ')');
      } else {
        logger.info('[alice-dms-scanner] stale path removed, alive at ' + stillAlive.length + ' other path(s): ' + filePath);
      }
    }
  }
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
  logger.info('[alice-dms-scanner] stale path check error: ' + e.message);
}

outputItems.push({ json: { _stale_for_deletion: false, ...statsItem, deleted_files: deletedFiles } });
return outputItems;
